/**
 * Rehype plugin for :::file-tree directive (Vuepress Plume-inspired design).
 *
 * Uses vscode-icons (via @iconify-json/vscode-icons) for per-file-type icons.
 * Icon data is generated by scripts/generate-file-icons.mjs.
 *
 * HTML structure:
 *   <div class="vp-file-tree">
 *     <div class="vp-file-tree-node">
 *       <p class="vp-file-tree-info {folder|file} [expanded] [diff-add|diff-remove]"
 *          style="--file-tree-level: -{level}">
 *         <span class="vp-file-tree-arrow">...</span>   <!-- folders only -->
 *         <span class="vp-file-tree-arrow-spacer"/>      <!-- files only -->
 *         <span class="vp-file-tree-icon">...</span>
 *         <span class="vp-file-tree-name {folder|file}">name</span>
 *         <span class="vp-file-tree-comment">comment</span>
 *       </p>
 *       <div class="vp-file-tree-group">   <!-- only for folders with children -->
 *         <!-- child nodes -->
 *       </div>
 *     </div>
 *   </div>
 *
 * Uses <details>/<summary> for expand/collapse since we can't use Vue reactivity.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { visit } from "unist-util-visit";

const __dirname = dirname(fileURLToPath(import.meta.url));

// Load icon data generated by scripts/generate-file-icons.mjs
let iconData;
try {
	iconData = JSON.parse(
		readFileSync(join(__dirname, "file-icons.json"), "utf-8"),
	);
} catch {
	// Fallback minimal data if file-icons.json hasn't been generated yet
	iconData = {
		icons: {
			"default-file": {
				body: '<path fill="#c5c5c5" d="M20.414 2H5v28h22V8.586ZM7 28V4h12v6h6v18Z"/>',
				viewBox: "0 0 32 32",
			},
			"default-folder": {
				body: '<path fill="#dcb67a" d="M2 4v24h28V8H14l-4-4z"/>',
				viewBox: "0 0 32 32",
			},
			"default-folder-opened": {
				body: '<path fill="#dcb67a" d="M2 4v24h28V8H14l-4-4z"/><path fill="#e8d5a3" d="M2 12v16h28V12z"/>',
				viewBox: "0 0 32 32",
			},
		},
		fileMap: {},
		folderMap: {},
		folderOpenMap: {},
		defaultFile: "default-file",
		defaultFolder: "default-folder",
		defaultFolderOpen: "default-folder-opened",
		chevron: {
			body: '<path fill="currentColor" d="m5.157 13.069l4.611-4.685a.546.546 0 0 0 0-.768L5.158 2.93a.55.55 0 0 1 0-.771a.53.53 0 0 1 .759 0l4.61 4.684a1.65 1.65 0 0 1 0 2.312l-4.61 4.684a.53.53 0 0 1-.76 0a.55.55 0 0 1 0-.771"/>',
			viewBox: "0 0 16 16",
		},
		ellipsis: {
			body: '<circle fill="#94a3b8" cx="4" cy="8" r="1.5"/><circle fill="#94a3b8" cx="8" cy="8" r="1.5"/><circle fill="#94a3b8" cx="12" cy="8" r="1.5"/>',
			viewBox: "0 0 16 16",
		},
		defaultIcon: "default-file",
	};
}

function el(tag, props, children) {
	return {
		type: "element",
		tagName: tag,
		properties: props || {},
		children: children || [],
	};
}

function txt(value) {
	return { type: "text", value };
}

/**
 * Build an inline <svg> element with the given icon content.
 * Each icon carries its own viewBox matching its native coordinate system.
 */
function svgIcon(iconEntry, extraClass) {
	const body = typeof iconEntry === "string" ? iconEntry : iconEntry.body;
	const viewBox =
		typeof iconEntry === "string" ? "0 0 32 32" : iconEntry.viewBox;
	const props = {
		xmlns: "http://www.w3.org/2000/svg",
		viewBox,
	};
	if (extraClass) {
		props.class = extraClass;
	}
	return el("svg", props, [{ type: "raw", value: body }]);
}

/**
 * Resolve the icon name for a file by its name/extension.
 * Checks: exact filename match → base filename match → extension match → default.
 */
function resolveFileIcon(filename) {
	const lower = filename.toLowerCase();

	// Check exact filename match (e.g. "README.md", ".gitignore")
	if (iconData.fileMap[lower]) return iconData.fileMap[lower];

	// Check base filename (e.g. "package.json" from "some/package.json")
	const base = filename.split("/").pop() || filename;
	const baseLower = base.toLowerCase();
	if (iconData.fileMap[baseLower]) return iconData.fileMap[baseLower];

	// Check extension
	const ext = base.split(".").pop()?.toLowerCase() || "";
	if (iconData.fileMap[ext]) return iconData.fileMap[ext];

	return iconData.defaultFile || iconData.defaultIcon;
}

/**
 * Resolve the icon name for a folder by its name.
 * Checks: folder name match → opened variant if expanded → default folder icon.
 */
function resolveFolderIcon(folderName, isOpen) {
	const lower = folderName.toLowerCase();
	const closedName = iconData.folderMap?.[lower];
	if (closedName && iconData.icons[closedName]) {
		if (isOpen) {
			const openName = iconData.folderOpenMap?.[closedName];
			if (openName && iconData.icons[openName]) return openName;
		}
		return closedName;
	}
	return isOpen
		? iconData.defaultFolderOpen || iconData.defaultFolder
		: iconData.defaultFolder;
}

/**
 * Get the full icon entry (body + viewBox) for a resolved icon name.
 */
function getIconEntry(iconName) {
	if (iconName && iconData.icons[iconName]) {
		return iconData.icons[iconName];
	}
	return (
		iconData.icons[iconData.defaultFile || iconData.defaultIcon] ||
		iconData.icons["default-file"]
	);
}

function hastText(node) {
	if (!node) return "";
	if (node.type === "text") return node.value;
	if (Array.isArray(node.children)) return node.children.map(hastText).join("");
	return "";
}

function parseItemText(text) {
	let name = text.trim();
	let comment = "";
	let diffType = null;

	const commentMatch = name.match(/\s+#\s+(.+)$/);
	if (commentMatch) {
		comment = commentMatch[1].trim();
		name = name.slice(0, name.length - commentMatch[0].length).trim();
	}

	if (name.startsWith("++ ")) {
		diffType = "add";
		name = name.slice(3).trim();
	} else if (name.startsWith("-- ")) {
		diffType = "remove";
		name = name.slice(3).trim();
	}

	const isFolder = name.endsWith("/");
	if (isFolder) name = name.slice(0, -1);
	const isEllipsis = name === "..." || name === "…";

	return { name, comment, diffType, isFolder, isEllipsis };
}

function parseLiElement(li) {
	let text = "";
	let childList = null;

	for (const child of li.children || []) {
		if (child.tagName === "p" && !childList) {
			text = hastText(child);
		} else if (child.tagName === "ul" || child.tagName === "ol") {
			childList = child;
		} else if (child.type === "text" && !text) {
			text = child.value;
		}
	}

	const parsed = parseItemText(text);
	const node = { ...parsed, children: [] };

	if (childList) {
		for (const child of childList.children || []) {
			if (child.tagName === "li") {
				node.children.push(parseLiElement(child));
			}
		}
	}

	return node;
}

function parseListElement(list) {
	const nodes = [];
	for (const child of list.children || []) {
		if (child.tagName === "li") {
			nodes.push(parseLiElement(child));
		}
	}
	return nodes;
}

/**
 * Build HAST for a single tree node.
 */
function buildNodeHast(node, level) {
	const { name, comment, diffType, isFolder, isEllipsis, children } = node;

	const levelStyle = `--file-tree-level: -${level};`;

	// Ellipsis node
	if (isEllipsis) {
		const infoKids = [
			el("span", { className: ["vp-file-tree-arrow-spacer"] }),
			el(
				"span",
				{ className: ["vp-file-tree-icon", "vp-file-tree-ellipsis"] },
				[svgIcon(iconData.ellipsis)],
			),
			el(
				"span",
				{ className: ["vp-file-tree-name", "vp-file-tree-ellipsis-text"] },
				[txt("…")],
			),
		];
		return el("div", { className: ["vp-file-tree-node"] }, [
			el(
				"p",
				{ className: ["vp-file-tree-info", "file"], style: levelStyle },
				infoKids,
			),
		]);
	}

	const infoClasses = ["vp-file-tree-info", isFolder ? "folder" : "file"];
	if (diffType) {
		infoClasses.push("diff", diffType === "add" ? "add" : "remove");
	}

	const infoKids = [];

	if (diffType) {
		infoKids.push(
			el(
				"span",
				{
					className: [
						"vp-file-tree-diff-indicator",
						diffType === "add" ? "add" : "remove",
					],
				},
				[txt(diffType === "add" ? "+" : "−")],
			),
		);
	} else {
		infoKids.push(el("span", { className: ["vp-file-tree-diff-indicator"] }));
	}

	if (isFolder) {
		// Arrow (chevron)
		infoKids.push(
			el("span", { className: ["vp-file-tree-arrow"] }, [
				svgIcon(iconData.chevron, "vp-file-tree-arrow-icon"),
			]),
		);
		// Folder icon — resolve by folder name for specialized icons
		const isOpen = level === 0;
		const folderIconName = resolveFolderIcon(name, isOpen);
		const folderEntry = getIconEntry(folderIconName);
		infoKids.push(
			el("span", { className: ["vp-file-tree-icon"] }, [svgIcon(folderEntry)]),
		);
	} else {
		// Spacer (same width as arrow) to keep alignment
		infoKids.push(el("span", { className: ["vp-file-tree-arrow-spacer"] }));
		// File icon — per-file-type from vscode-icons
		const iconName = resolveFileIcon(name);
		const iconEntry = getIconEntry(iconName);
		infoKids.push(
			el("span", { className: ["vp-file-tree-icon"] }, [svgIcon(iconEntry)]),
		);
	}

	// Name
	infoKids.push(
		el(
			"span",
			{ className: ["vp-file-tree-name", isFolder ? "folder" : "file"] },
			[txt(name)],
		),
	);

	// Comment
	if (comment) {
		infoKids.push(
			el("span", { className: ["vp-file-tree-comment"] }, [txt(comment)]),
		);
	}

	const infoEl = el(
		"p",
		{ className: infoClasses, style: levelStyle },
		infoKids,
	);

	if (!isFolder) {
		return el("div", { className: ["vp-file-tree-node"] }, [infoEl]);
	}

	if (children.length === 0) {
		return el("div", { className: ["vp-file-tree-node"] }, [infoEl]);
	}

	// Folder with children: use <details>/<summary> for expand/collapse
	const childLevel = level + 1;
	const childNodes = children.map((c) => buildNodeHast(c, childLevel));
	const groupEl = el(
		"div",
		{
			className: ["vp-file-tree-group"],
			style: `--file-tree-level: -${childLevel};`,
		},
		childNodes,
	);

	const isOpen = level === 0;
	if (isOpen) {
		infoClasses.push("expanded");
	}

	return el("div", { className: ["vp-file-tree-node"] }, [
		el("details", { open: isOpen }, [el("summary", {}, [infoEl]), groupEl]),
	]);
}

function buildFileTreeHast(nodes) {
	const childNodes = nodes.map((n) => buildNodeHast(n, 0));
	return el("div", { className: ["vp-file-tree"] }, childNodes);
}

export function rehypeFileTreeV3() {
	return (tree) => {
		visit(tree, "element", (node, index, parent) => {
			if (node.tagName !== "file-tree") return;
			if (!parent || typeof index !== "number") return;

			const listEl = node.children?.find(
				(c) =>
					c.type === "element" && (c.tagName === "ul" || c.tagName === "ol"),
			);

			if (!listEl) {
				parent.children[index] = el("div", { className: ["vp-file-tree"] }, []);
				return;
			}

			const treeNodes = parseListElement(listEl);
			const hast = buildFileTreeHast(treeNodes);

			parent.children[index] = hast;
		});
	};
}
